export const USER_WORKSPACE_RUNTIME_SHA256 = "e287ff777ad965573fe0a4f7832c51774ef7de680f9e52c0c66d9505383ee824";
export const USER_WORKSPACE_DATA_MIGRATIONS = [{"name":"0001_user_workspace.sql","sql":"CREATE TABLE chats (\n  id TEXT PRIMARY KEY,\n  creator_id TEXT NOT NULL,\n  initial_id TEXT NOT NULL,\n  url_id TEXT,\n  description TEXT,\n  timestamp TEXT NOT NULL,\n  last_subchat_index INTEGER NOT NULL DEFAULT 0,\n  is_deleted INTEGER NOT NULL DEFAULT 0 CHECK (is_deleted IN (0, 1))\n);\n\nCREATE UNIQUE INDEX idx_chats_active_initial\nON chats(creator_id, initial_id) WHERE is_deleted = 0;\nCREATE UNIQUE INDEX idx_chats_active_url\nON chats(creator_id, url_id) WHERE is_deleted = 0 AND url_id IS NOT NULL;\nCREATE INDEX idx_chats_history\nON chats(creator_id, is_deleted, timestamp DESC, id DESC);\n\nCREATE TABLE chat_transcripts (\n  chat_id TEXT NOT NULL,\n  subchat_index INTEGER NOT NULL CHECK (subchat_index >= 0),\n  generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0),\n  agent_name TEXT NOT NULL UNIQUE,\n  head_revision INTEGER NOT NULL DEFAULT 0 CHECK (head_revision >= 0),\n  head_digest TEXT,\n  head_message_count INTEGER NOT NULL DEFAULT 0 CHECK (head_message_count >= 0),\n  last_message_rank INTEGER NOT NULL DEFAULT -1 CHECK (last_message_rank >= -1),\n  part_index INTEGER NOT NULL DEFAULT -1 CHECK (part_index >= -1),\n  description TEXT,\n  parent_subchat_index INTEGER,\n  parent_generation INTEGER,\n  parent_revision INTEGER,\n  transition_token TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  PRIMARY KEY (chat_id, subchat_index),\n  FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE\n);\n\nCREATE TABLE agent_gc_candidates (\n  chat_id TEXT NOT NULL,\n  initial_id TEXT NOT NULL,\n  subchat_index INTEGER NOT NULL CHECK (subchat_index >= 0),\n  next_generation INTEGER NOT NULL DEFAULT 0 CHECK (next_generation >= 0),\n  max_generation INTEGER NOT NULL CHECK (max_generation >= next_generation),\n  not_before INTEGER NOT NULL,\n  created_at INTEGER NOT NULL,\n  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),\n  PRIMARY KEY (chat_id, subchat_index)\n);\n\nCREATE INDEX idx_agent_gc_due\nON agent_gc_candidates(not_before, chat_id, subchat_index);\n\nCREATE TABLE deployments (\n  id TEXT PRIMARY KEY,\n  chat_id TEXT NOT NULL,\n  user_id TEXT NOT NULL,\n  connection_id TEXT NOT NULL,\n  connection_generation INTEGER NOT NULL CHECK (connection_generation > 0),\n  execution_generation INTEGER NOT NULL DEFAULT 0 CHECK (execution_generation >= 0),\n  workspace_reference TEXT NOT NULL,\n  status TEXT NOT NULL CHECK (\n    status IN ('awaiting_approval', 'approved', 'provisioning', 'deploying', 'succeeded', 'failed')\n  ),\n  plan_json TEXT NOT NULL,\n  plan_digest TEXT NOT NULL,\n  approved_digest TEXT,\n  approved_at INTEGER,\n  production_url TEXT,\n  error_code TEXT,\n  error_message TEXT,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_deployments_user_created\nON deployments(user_id, created_at DESC);\nCREATE INDEX idx_deployments_chat_created\nON deployments(chat_id, created_at DESC);\nCREATE INDEX idx_deployments_status_updated\nON deployments(status, updated_at);\n\nCREATE TABLE deployment_resources (\n  id TEXT PRIMARY KEY,\n  deployment_id TEXT NOT NULL,\n  resource_type TEXT NOT NULL,\n  logical_name TEXT NOT NULL,\n  provider_resource_id TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  FOREIGN KEY (deployment_id) REFERENCES deployments(id) ON DELETE CASCADE,\n  UNIQUE (deployment_id, resource_type, logical_name)\n);\n"},{"name":"0002_remove_chat_url_id.sql","sql":"-- Chat identity is the immutable initial_id. Remove the unused alternate URL identity.\nDROP INDEX idx_chats_active_url;\nALTER TABLE chats DROP COLUMN url_id;\n"},{"name":"0003_app_resource_gc.sql","sql":"CREATE TABLE app_resource_gc_candidates (\n  chat_id TEXT PRIMARY KEY,\n  not_before INTEGER NOT NULL,\n  created_at INTEGER NOT NULL,\n  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),\n  FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_app_resource_gc_due\nON app_resource_gc_candidates(not_before, chat_id);\n\n-- Projects removed before this migration must receive the same provider cleanup.\nINSERT INTO app_resource_gc_candidates (chat_id, not_before, created_at, attempts)\nSELECT id, 0, 0, 0 FROM chats WHERE is_deleted = 1;\n"},{"name":"0004_chat_title_sources.sql","sql":"-- Track automatic titles explicitly so later conversation prompts can refresh\n-- generated labels without racing or overwriting a manual rename.\nALTER TABLE chats ADD COLUMN description_source TEXT\n  CHECK (description_source IN ('heuristic', 'generated', 'user'));\n\nALTER TABLE chat_transcripts ADD COLUMN description_source TEXT\n  CHECK (description_source IN ('heuristic', 'generated', 'user'));\n\nALTER TABLE chat_transcripts ADD COLUMN description_generation INTEGER NOT NULL DEFAULT 0\n  CHECK (description_generation >= 0);\n\n-- Existing labels may have been manually edited. Preserve them conservatively.\nUPDATE chats\nSET description_source = 'user'\nWHERE NULLIF(TRIM(description), '') IS NOT NULL;\n\nUPDATE chat_transcripts\nSET description_source = 'user'\nWHERE NULLIF(TRIM(description), '') IS NOT NULL;\n"},{"name":"0005_deployment_activity.sql","sql":"CREATE TABLE deployment_activity (\n  deployment_id TEXT NOT NULL,\n  execution_generation INTEGER NOT NULL CHECK (execution_generation > 0),\n  sequence INTEGER NOT NULL CHECK (sequence > 0),\n  message TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  PRIMARY KEY (deployment_id, execution_generation, sequence),\n  FOREIGN KEY (deployment_id) REFERENCES deployments(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_deployment_activity_current\nON deployment_activity(deployment_id, execution_generation, sequence);\n"},{"name":"0006_runtime_controls.sql","sql":"-- Operator kill switch for the preview-only @cloudflare/computer runtime.\n-- Setting enabled to 0 stops the runtime from admitting new Computer-backed\n-- operations without redeploying it. Durable project data stays readable.\nCREATE TABLE runtime_controls (\n  key TEXT PRIMARY KEY,\n  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),\n  reason TEXT,\n  updated_at INTEGER NOT NULL\n);\n\nINSERT INTO runtime_controls (key, enabled, reason, updated_at)\nVALUES ('computer_operations', 1, NULL, unixepoch() * 1000);\n"}] as const;
